<?php

namespace Database\Seeders;

use App\Models\Article;
use App\Models\ArticleCategory;
use App\Models\Service;
use Illuminate\Database\Seeder;

class LaunchArticleSeeder extends Seeder
{
    public function run(): void
    {
        $category = ArticleCategory::query()->firstOrCreate(
            ['name' => 'دليل المظلات والسواتر'],
            ['description' => 'مقالات عملية لفهم الخامات والتصاميم والمعاينة والتكلفة والصيانة قبل اتخاذ القرار.', 'is_active' => true],
        );
        $serviceIds = Service::query()->pluck('id', 'name');

        foreach ($this->articles() as $data) {
            $article = Article::query()->firstOrCreate(['title' => $data['title']], [
                'article_category_id' => $category->id,
                'excerpt' => $data['excerpt'],
                'body' => $data['body'],
                'status' => 'published',
                'published_at' => now(),
            ]);

            $article->services()->syncWithoutDetaching(
                collect($data['services'])->map(fn (string $name) => $serviceIds->get($name))->filter()->values()
            );
            $article->seo()->firstOrCreate([], [
                'meta_title' => $data['title'],
                'meta_description' => $data['excerpt'],
                'robots' => 'index,follow,max-image-preview:large',
                'schema_type' => 'Article',
            ]);
        }
    }

    private function articles(): array
    {
        return [
            [
                'title' => 'أسعار مظلات السيارات في الرياض والعوامل التي تحدد التكلفة',
